import { BusinessFailure } from './BusinessFailure.ts';

/** Señal interna: se intentó leer un parámetro de negocio inexistente. */
export class MissingParameterError extends Error {
  readonly failure: BusinessFailure;

  constructor(parameterCode: string) {
    super(`Parametro no definido: ${parameterCode}`);
    this.failure = BusinessFailure.missingParameter(parameterCode);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { MissingParameterError } from '../exceptions/MissingParameterError.ts';

export const ParameterCode = {
  MAX_REPORT_DAYS: 'DIAS_MAX_DENUNCIA',
  MAX_REPORT_DAYS_LIFE: 'DIAS_MAX_DENUNCIA_VIDA',
  MINIMUM_DEDUCTIBLE: 'DEDUCIBLE_MINIMO',
  VIP_DEDUCTIBLE_DISCOUNT_PCT: 'PCT_DESCUENTO_DED_VIP',
  VIP_ARREARS_TOLERANCE: 'TOLERANCIA_MORA_VIP',
  MAX_ANNUAL_CLAIMS: 'MAX_SINIESTROS_ANUAL',
  CLAIM_FREQUENCY_PENALTY_PCT: 'PCT_PENALIZACION_SINIEST',
  WITHHOLDING_THRESHOLD: 'UMBRAL_RETENCION',
  WITHHOLDING_RATE_PCT: 'TASA_RETENCION',
  AUTO_APPROVAL_LIMIT: 'TOPE_AUTO_APROBACION',
  FRAUD_ALERT_DAYS: 'DIAS_ALERTA_FRAUDE',
  FRAUD_ALERT_PCT: 'PCT_ALERTA_FRAUDE',
  INFLATION_FACTOR: 'FACTOR_INFLACION',
} as const;

/**
 * Parámetros de negocio tipados. Cada lectura es perezosa, como fn_param_num del legacy:
 * solo falla (ORA-20010) el parámetro que realmente se necesita.
 * @rule R-023
 */
export class BusinessParameters {
  private readonly values: ReadonlyMap<string, Decimal>;

  constructor(values: ReadonlyMap<string, Decimal>) {
    this.values = values;
  }

  /** @rule R-023 */
  has(code: string): boolean {
    return this.values.has(code);
  }

  /** @rule R-023 */
  private require(code: string): Decimal {
    const value = this.values.get(code);
    if (value === undefined) {
      throw new MissingParameterError(code);
    }
    return value;
  }

  get maxReportDays(): Decimal {
    return this.require(ParameterCode.MAX_REPORT_DAYS);
  }

  get maxReportDaysLife(): Decimal {
    return this.require(ParameterCode.MAX_REPORT_DAYS_LIFE);
  }

  get minimumDeductible(): Decimal {
    return this.require(ParameterCode.MINIMUM_DEDUCTIBLE);
  }

  get vipDeductibleDiscountPct(): Decimal {
    return this.require(ParameterCode.VIP_DEDUCTIBLE_DISCOUNT_PCT);
  }

  get vipArrearsTolerance(): Decimal {
    return this.require(ParameterCode.VIP_ARREARS_TOLERANCE);
  }

  get maxAnnualClaims(): Decimal {
    return this.require(ParameterCode.MAX_ANNUAL_CLAIMS);
  }

  get claimFrequencyPenaltyPct(): Decimal {
    return this.require(ParameterCode.CLAIM_FREQUENCY_PENALTY_PCT);
  }

  get withholdingThreshold(): Decimal {
    return this.require(ParameterCode.WITHHOLDING_THRESHOLD);
  }

  get withholdingRatePct(): Decimal {
    return this.require(ParameterCode.WITHHOLDING_RATE_PCT);
  }

  get autoApprovalLimit(): Decimal {
    return this.require(ParameterCode.AUTO_APPROVAL_LIMIT);
  }

  get fraudAlertDays(): Decimal {
    return this.require(ParameterCode.FRAUD_ALERT_DAYS);
  }

  get fraudAlertPct(): Decimal {
    return this.require(ParameterCode.FRAUD_ALERT_PCT);
  }
}

import type { ClaimCase } from '../model/ClaimCase.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import { Decimal } from '../shared/decimal.ts';
import { roundedPercentOf } from '../services/rounding.ts';

export class FraudAlertSpecification {
  /**
   * Ocurrencia dentro de los primeros DIAS_ALERTA_FRAUDE días (inclusive) y reclamo >= PCT_ALERTA_FRAUDE% del límite.
   * El umbral se calcula primero, como en el legacy.
   * @rule R-017
   */
  isSatisfiedBy(claim: ClaimCase, parameters: BusinessParameters): boolean {
    const highClaim = this.isHighClaim(claim, parameters);
    const early = this.isEarlyInPolicy(claim, parameters);
    return early && highClaim;
  }

  /** @rule R-017 */
  private isEarlyInPolicy(claim: ClaimCase, parameters: BusinessParameters): boolean {
    const daysSinceStart = claim.claim.occurrenceDate.daysSince(claim.policy.startDate);
    return Decimal.of(daysSinceStart).lte(parameters.fraudAlertDays);
  }

  /** @rule R-017 */
  private isHighClaim(claim: ClaimCase, parameters: BusinessParameters): boolean {
    const threshold = roundedPercentOf(claim.coverage.limit, parameters.fraudAlertPct);
    return claim.claim.claimedAmount.gte(threshold);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { ClaimCase } from '../model/ClaimCase.ts';
import { BusinessFailure } from '../exceptions/BusinessFailure.ts';
import { MissingParameterError } from '../exceptions/MissingParameterError.ts';
import { BusinessParameters, ParameterCode } from '../model/BusinessParameters.ts';
import { Observations } from '../model/Observations.ts';
import { Settlement } from '../model/Settlement.ts';
import { SettlementOutcome } from '../model/SettlementOutcome.ts';
import { CalculatedAmounts, Rejection } from '../model/StepResults.ts';
import type { RegisteredClaimSpecification } from '../specifications/RegisteredClaimSpecification.ts';
import type { EligibilityPolicy } from './EligibilityPolicy.ts';
import type { AmountCalculator } from './AmountCalculator.ts';
import type { ApprovalPolicy } from './ApprovalPolicy.ts';
import { ZERO_AMOUNT } from './rounding.ts';

/** Servicio de dominio que orquesta la liquidación completa de un siniestro. */
export class ClaimSettlementService {
  private readonly registeredSpecification: RegisteredClaimSpecification;
  private readonly eligibility: EligibilityPolicy;
  private readonly calculator: AmountCalculator;
  private readonly approval: ApprovalPolicy;

  constructor(
    registeredSpecification: RegisteredClaimSpecification,
    eligibility: EligibilityPolicy,
    calculator: AmountCalculator,
    approval: ApprovalPolicy,
  ) {
    this.registeredSpecification = registeredSpecification;
    this.eligibility = eligibility;
    this.calculator = calculator;
    this.approval = approval;
  }

  /**
   * Comprueba que el siniestro esté REGISTRADO y que exista FACTOR_INFLACION (siempre se lee);
   * el resto de parámetros se exigen solo cuando se usan. Luego liquida.
   * @rule R-001
   * @rule R-023
   */
  settleClaim(claim: ClaimCase, parameterValues: ReadonlyMap<string, Decimal>): SettlementOutcome {
    if (!this.registeredSpecification.isSatisfiedBy(claim)) {
      return SettlementOutcome.failed(BusinessFailure.claimNotRegistered(claim.claimId, claim.claim.status));
    }
    if (!parameterValues.has(ParameterCode.INFLATION_FACTOR)) {
      return SettlementOutcome.failed(BusinessFailure.missingParameter(ParameterCode.INFLATION_FACTOR));
    }
    try {
      return SettlementOutcome.succeeded(this.settle(claim, new BusinessParameters(parameterValues)));
    } catch (error) {
      if (error instanceof MissingParameterError) {
        return SettlementOutcome.failed(error.failure);
      }
      throw error;
    }
  }

  /**
   * Elegibilidad (R-002 a R-008), cálculo (R-009 a R-016) y decisión de aprobación (R-017, R-018).
   * @rule R-008
   * @rule R-017
   * @rule R-018
   * @rule R-019
   * @rule R-020
   */
  settle(claim: ClaimCase, parameters: BusinessParameters): Settlement {
    const eligibility = this.eligibility.evaluate(claim, parameters);
    if (eligibility instanceof Rejection) {
      return this.reject(claim, eligibility);
    }
    const amounts = this.calculator.calculate(claim, parameters, eligibility);
    if (amounts instanceof Rejection) {
      return this.reject(claim, amounts);
    }
    const decision = this.approval.decide(claim, parameters, amounts.net);
    return new Settlement(decision.status, decision.reason, claim.claim.claimedAmount, amounts, claim.claim.processDate);
  }

  /** @rule R-019 */
  private reject(claim: ClaimCase, rejection: Rejection): Settlement {
    const zeros = new CalculatedAmounts(
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      ZERO_AMOUNT,
      rejection.observations,
    );
    return Settlement.rejected(
      rejection.reason,
      Observations.empty(),
      claim.claim.claimedAmount,
      claim.claim.processDate,
      zeros,
    );
  }
}

import type { ClaimSettlementService } from '../../domain/services/ClaimSettlementService.ts';
import type { SettlementOutcome } from '../../domain/model/SettlementOutcome.ts';
import type { SettleClaimRequest, SettleClaimUseCase } from '../ports/in/SettleClaimUseCase.ts';
import type { SettlementAuditEntry, SettlementAuditPort } from '../ports/out/SettlementAuditPort.ts';

export class SettleClaimService implements SettleClaimUseCase {
  private readonly settlementService: ClaimSettlementService;
  private readonly audit: SettlementAuditPort;

  constructor(settlementService: ClaimSettlementService, audit: SettlementAuditPort) {
    this.settlementService = settlementService;
    this.audit = audit;
  }

  execute(request: SettleClaimRequest): SettlementOutcome {
    const outcome = this.settlementService.settleClaim(request.claim, request.parameterValues);
    this.audit.record(this.toAuditEntry(request.claim.claimId, outcome));
    return outcome;
  }

  private toAuditEntry(claimId: string, outcome: SettlementOutcome): SettlementAuditEntry {
    if (outcome.failure !== null) {
      return { claimId, result: outcome.failure.code, detail: outcome.failure.message };
    }
    const settlement = outcome.settlement;
    return {
      claimId,
      result: settlement === null ? '' : settlement.status,
      detail: settlement === null ? '' : settlement.reasonCode,
    };
  }
}

import type { Decimal } from '../../../domain/shared/decimal.ts';
import type { BusinessFailure } from '../../../domain/exceptions/BusinessFailure.ts';
import type { Settlement } from '../../../domain/model/Settlement.ts';
import type { SettlementOutcome } from '../../../domain/model/SettlementOutcome.ts';

const ZERO = '0.00';

function money(amount: Decimal): string {
  return amount.setScale(2, 'HALF_UP').toString();
}

function settlementRecord(settlement: Settlement): Record<string, string> {
  return {
    status: settlement.status,
    reason_code: settlement.reasonCode,
    base_amount: money(settlement.baseAmount),
    deductible_amount: money(settlement.deductibleAmount),
    covered_amount: money(settlement.coveredAmount),
    withholding_amount: money(settlement.withholdingAmount),
    net_amount: money(settlement.netAmount),
    observations: settlement.observations.toNullable() ?? '',
    claim_final_status: settlement.finalClaimStatus,
    error_code: '',
    error_message: '',
  };
}

/**
 * Salida para un error: status 'ERROR' e importes en cero.
 * reason_code y claim_final_status se informan solo si se indican (error de negocio).
 */
export function failureRecord(
  failure: BusinessFailure,
  reasonCode: string,
  claimStatus: string,
): Record<string, string> {
  return {
    status: 'ERROR',
    reason_code: reasonCode,
    base_amount: ZERO,
    deductible_amount: ZERO,
    covered_amount: ZERO,
    withholding_amount: ZERO,
    net_amount: ZERO,
    observations: '',
    claim_final_status: claimStatus,
    error_code: failure.code,
    error_message: failure.message,
  };
}

/** Convierte el resultado del dominio a un registro de cadenas. */
export function outcomeRecord(outcome: SettlementOutcome, currentClaimStatus: string): Record<string, string> {
  if (outcome.failure !== null) {
    return failureRecord(outcome.failure, outcome.failure.code, currentClaimStatus);
  }
  return settlementRecord(outcome.settlement as Settlement);
}

import type { SettleClaimUseCase } from '../../../application/ports/in/SettleClaimUseCase.ts';
import { BusinessFailure } from '../../../domain/exceptions/BusinessFailure.ts';
import { ClaimInputMapper } from './ClaimInputMapper.ts';
import { failureRecord, outcomeRecord } from './SettlementResponseMapper.ts';

/** Adaptador de entrada: strings a dominio, ejecuta el caso de uso y devuelve strings. */
export class ClaimEntryAdapter {
  private readonly useCase: SettleClaimUseCase;
  private readonly mapper: ClaimInputMapper;

  constructor(useCase: SettleClaimUseCase, mapper: ClaimInputMapper) {
    this.useCase = useCase;
    this.mapper = mapper;
  }

  handle(input: Record<string, string>): Record<string, string> {
    const mapped = this.mapper.map(input);
    if (mapped.request === null) {
      return failureRecord(new BusinessFailure('INVALID_INPUT', mapped.problems.join(' | ')), '', '');
    }
    const outcome = this.useCase.execute(mapped.request);
    return outcomeRecord(outcome, mapped.request.claim.claim.status);
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execute } from '../src/index.ts';

const PARAMS =
  'DIAS_MAX_DENUNCIA=30;DIAS_MAX_DENUNCIA_VIDA=365;DEDUCIBLE_MINIMO=100;PCT_DESCUENTO_DED_VIP=50;' +
  'TOLERANCIA_MORA_VIP=500;MAX_SINIESTROS_ANUAL=3;PCT_PENALIZACION_SINIEST=10;UMBRAL_RETENCION=10000;' +
  'TASA_RETENCION=2;TOPE_AUTO_APROBACION=50000;DIAS_ALERTA_FRAUDE=15;PCT_ALERTA_FRAUDE=80;FACTOR_INFLACION=1.035';

function baseInput(): Record<string, string> {
  return {
    claim_id: '1',
    process_date: '2026-03-10',
    claimed_amount: '5000.00',
    occurrence_date: '2026-03-01',
    report_date: '2026-03-05',
    coverage_code: 'COL',
    claim_status: 'REGISTRADO',
    policy_status: 'VIGENTE',
    policy_branch: 'AUTO',
    policy_start_date: '2026-01-01',
    policy_end_date: '2026-12-31',
    sum_insured: '100000.00',
    deductible_type: 'FIJO',
    deductible_value: '200.00',
    pending_premium: '0.00',
    customer_category: 'ESTANDAR',
    coverage_found: 'true',
    coverage_limit: '10000.00',
    coverage_pct: '80.00',
    waiting_days: '0',
    prior_liquidated_claims_365d: '0',
    total_indemnified: '0.00',
    params: PARAMS,
  };
}

test('aprueba automáticamente una liquidación estándar', () => {
  const out = execute(baseInput());
  assert.equal(out.status, 'APROBADA');
  assert.equal(out.reason_code, 'LIQUIDACION_AUTOMATICA');
  assert.equal(out.covered_amount, '3840.00');
  assert.equal(out.net_amount, '3840.00');
  assert.equal(out.claim_final_status, 'LIQUIDADO');
});

test('rechaza una póliza no vigente con importes en cero', () => {
  const out = execute({ ...baseInput(), policy_status: 'CANCELADA' });
  assert.equal(out.status, 'RECHAZADA');
  assert.equal(out.reason_code, 'POLIZA_NO_VIGENTE');
  assert.equal(out.net_amount, '0.00');
  assert.equal(out.claim_final_status, 'RECHAZADO');
});

test('devuelve ORA-20001 si el siniestro no está REGISTRADO', () => {
  const out = execute({ ...baseInput(), claim_status: 'LIQUIDADO' });
  assert.equal(out.status, 'ERROR');
  assert.equal(out.error_code, 'ORA-20001');
  assert.equal(out.reason_code, 'ORA-20001');
  assert.equal(out.claim_final_status, 'LIQUIDADO');
});

test('un parámetro no usado que falta no provoca error', () => {
  const params = PARAMS.replace('TOLERANCIA_MORA_VIP=500;', '');
  const out = execute({ ...baseInput(), params });
  assert.equal(out.status, 'APROBADA');
});

test('un parámetro usado que falta devuelve ORA-20010', () => {
  const params = PARAMS.replace('TASA_RETENCION=2;', '');
  const out = execute({ ...baseInput(), params, claimed_amount: '20000.00', coverage_limit: '30000.00' });
  assert.equal(out.status, 'ERROR');
  assert.equal(out.error_code, 'ORA-20010');
});
